package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// Data Division mappings
type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

var WsEofFlag string         // PIC X len=1 = "N"
var WsC decimal.Decimal      // PIC S9(3)V99 len=5 = 0
var WsFreeze int64           // PIC 99 len=2 = 0
var WsCount int64            // PIC 99 len=2 = 0
var WsFEd string             // PIC ZZ9.9 len=5
var WsCEd string             // PIC -ZZ9.99 len=7

// file/working items
var tempRec TempRec
var scanner *bufio.Scanner

// helpers for numeric fields

func pow10Int(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

// storeDecimal keeps only low-order digits that fit into picture intDigits.decDigits
func storeDecimal(val decimal.Decimal, intDigits, decDigits int, signed bool) decimal.Decimal {
	scaled := val.Shift(int32(decDigits)).Truncate(0)
	scaledInt := scaled.IntPart()
	totalDigits := intDigits + decDigits
	if totalDigits == 0 {
		return decimal.NewFromInt(0)
	}
	p := pow10Int(totalDigits)
	absScaled := scaledInt
	if absScaled < 0 {
		absScaled = -absScaled
	}
	mod := absScaled % p
	newScaled := mod
	if scaledInt < 0 && mod != 0 {
		newScaled = -mod
	} else if scaledInt < 0 && mod == 0 {
		newScaled = 0
	}
	return decimal.New(newScaled, int32(-decDigits))
}

func storeIntAdd(cur, delta int64, intDigits int) int64 {
	p := pow10Int(intDigits)
	v := cur + delta
	// keep low-order digits; for unsigned wrap around
	// Go % for negative needs correction but counts never negative here
	v = v % p
	if v < 0 {
		v += p
	}
	return v
}

// PIC 9(3)V9  scale 1
func parseTcF(s string) decimal.Decimal {
	if strings.TrimSpace(s) == "" {
		return decimal.NewFromInt(0)
	}
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else if ch == ' ' {
			b.WriteRune('0')
		} else {
			b.WriteRune('0')
		}
	}
	ds := b.String()
	n, err := strconv.ParseInt(ds, 10, 64)
	if err != nil {
		d, _ := decimal.NewFromString(ds)
		return d.Shift(-1)
	}
	return decimal.New(n, -1)
}

// formatEdited formats val according to COBOL numeric-edited picture
func formatEdited(val decimal.Decimal, pic string) string {
	signMode := rune(0)
	remainingPic := pic
	if len(pic) > 0 && (pic[0] == '-' || pic[0] == '+') {
		signMode = rune(pic[0])
		remainingPic = pic[1:]
	}
	isNeg := val.Sign() < 0 && !val.IsZero()
	absVal := val.Abs()

	signChar := ' '
	if signMode == '-' {
		if isNeg {
			signChar = '-'
		} else {
			signChar = ' '
		}
	} else if signMode == '+' {
		if isNeg {
			signChar = '-'
		} else {
			signChar = '+'
		}
	}

	dotPos := strings.Index(remainingPic, ".")
	var intPic, decPic string
	if dotPos >= 0 {
		intPic = remainingPic[:dotPos]
		decPic = remainingPic[dotPos+1:]
	} else {
		intPic = remainingPic
		decPic = ""
	}
	decDigits := len(decPic)
	intCap := 0
	for _, ch := range intPic {
		if ch == '9' || ch == 'Z' {
			intCap++
		}
	}

	truncated := absVal.Truncate(int32(decDigits))
	intPartDec := truncated.Truncate(0)
	intPartInt := intPartDec.IntPart()
	if intCap > 0 {
		p := pow10Int(intCap)
		intPartInt = intPartInt % p
		if intPartInt < 0 {
			intPartInt = -intPartInt
		}
	} else {
		intPartInt = 0
	}
	digitStr := fmt.Sprintf("%0*d", intCap, intPartInt)

	// placeholder sequence
	placeholderSeq := []rune{}
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			placeholderSeq = append(placeholderSeq, ch)
		}
	}
	firstNonZero := len(digitStr)
	for i, ch := range digitStr {
		if ch != '0' {
			firstNonZero = i
			break
		}
	}
	placeholderFormatted := make([]rune, len(placeholderSeq))
	for i, p := range placeholderSeq {
		d := rune(digitStr[i])
		if i < firstNonZero {
			if p == 'Z' {
				placeholderFormatted[i] = ' '
			} else {
				placeholderFormatted[i] = d // '0'
			}
		} else {
			placeholderFormatted[i] = d
		}
	}
	var intBuilder strings.Builder
	phIdx := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intBuilder.WriteRune(placeholderFormatted[phIdx])
			phIdx++
		} else if ch == ',' {
			allSpace := true
			for k := 0; k < phIdx; k++ {
				if placeholderFormatted[k] != ' ' {
					allSpace = false
					break
				}
			}
			if allSpace {
				intBuilder.WriteRune(' ')
			} else {
				intBuilder.WriteRune(',')
			}
		} else {
			intBuilder.WriteRune(ch)
		}
	}
	intFormatted := intBuilder.String()

	if decDigits > 0 {
		// fractional part
		totalScaled := truncated.Shift(int32(decDigits)).IntPart()
		pDec := pow10Int(decDigits)
		fracInt := totalScaled % pDec
		if fracInt < 0 {
			fracInt = -fracInt
		}
		fracStr := fmt.Sprintf("%0*d", decDigits, fracInt)
		var decBuilder strings.Builder
		fracIdx := 0
		for _, ch := range decPic {
			if ch == 'Z' || ch == '9' {
				if fracIdx < len(fracStr) {
					decBuilder.WriteByte(fracStr[fracIdx])
					fracIdx++
				}
			} else {
				decBuilder.WriteRune(ch)
			}
		}
		decFormatted := decBuilder.String()
		rem := intFormatted + "." + decFormatted
		if signMode == '-' || signMode == '+' {
			return string(signChar) + rem
		}
		return rem
	}
	if signMode == '-' || signMode == '+' {
		return string(signChar) + intFormatted
	}
	return intFormatted
}

// Paragraphs

func readPara() {
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		tempRec.TcSensor = line[0:4]
		s := line[4:8]
		tempRec.TcF = parseTcF(s)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func processPara() {
	tmp := tempRec.TcF.Sub(decimal.NewFromInt(32))
	tmp = tmp.Mul(decimal.NewFromInt(5))
	tmp = tmp.Div(decimal.NewFromInt(9))
	rounded := tmp.Round(2)
	WsC = storeDecimal(rounded, 3, 2, true)

	if WsC.Sign() < 0 {
		WsFreeze = storeIntAdd(WsFreeze, 1, 2)
	}
	WsCount = storeIntAdd(WsCount, 1, 2)

	WsFEd = formatEdited(tempRec.TcF, "ZZ9.9")
	WsCEd = formatEdited(WsC, "-ZZ9.99")

	line := tempRec.TcSensor + " " + WsFEd + "F " + WsCEd + "C\n"
	os.Stdout.WriteString(line)
	readPara()
}

func mainPara(f *os.File) {
	defer f.Close()
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	countStr := fmt.Sprintf("%02d", WsCount)
	freezeStr := fmt.Sprintf("%02d", WsFreeze)
	os.Stdout.WriteString("READINGS: " + countStr + " BELOW ZERO: " + freezeStr + "\n")
}

func main() {
	WsEofFlag = "N"
	WsC = decimal.NewFromInt(0)
	WsFreeze = 0
	WsCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	scanner = bufio.NewScanner(f)
	mainPara(f)
}
